/*
 * A170503  Number of reduced words of length n in Coxeter group on 14
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^46 = I.
 * https://oeis.org/A170503
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the recurrence produced by the rational *
 *            generating function of A170503. * * For n = 0 : a(0) = 1 * For 1
 *            ≤ n ≤ 45: * a(n) = 12 * (a(0)+a(1)+...+a(n-1)) + 2 * For n ≥ 46:
 *            * a(n) = 12 * (a(n-1)+a(n-2)+...+a(n-45)) - 78 * a(n-46)
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 8, u64 n <= 16, u128 n <= 16,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache  = NULL;
    static idx_t  size   = 0;
    static idx_t  max_calculated = 0;

    /* Ensure storage for indices up to n. */
    size_t new_size = (size_t)(n + 1);
    if (new_size > size) {
        seq_t *tmp = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
        if (!tmp) abort();
        cache = tmp;
        size = (idx_t)new_size;
    }

    /* Initialise the first term if this is the first call. */
    if (max_calculated == 0) {
        cache[0] = (seq_t)1;
        max_calculated = 0;
    }

    /* If the requested n is already known, return it. */
    if (n <= max_calculated) return cache[n];

    /* Compute new terms up to n. */
    /* 1. Compute the sum of all known terms up to max_calculated. */
    seq_t total_sum = 0;
    for (idx_t k = 0; k <= max_calculated; ++k)
        total_sum += cache[k];

    /* 2. Generate terms from max_calculated+1 up to n. */
    seq_t window_sum = 0;          /* Sum of the last 45 terms (when needed). */
    int   window_ready = 0;        /* Flag: has window_sum been initialised? */

    for (idx_t i = max_calculated + 1; i <= n; ++i) {
        if (i <= 45) {                  /* Initial recurrence. */
            seq_t val = 12 * total_sum + (seq_t)2;
            cache[i] = val;
            total_sum += val;
        } else {                        /* Main recurrence for n ≥ 46. */
            if (!window_ready) {        /* Initialise window_sum once. */
                window_sum = 0;
                for (idx_t k = i - 45; k <= i - 1; ++k)
                    window_sum += cache[k];
                window_ready = 1;
            }
            seq_t val = 12 * window_sum - 78 * cache[i - 46];
            cache[i] = val;
            window_sum += val - cache[i - 45];
        }
    }

    max_calculated = n;
    return cache[n];
}
